// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public {
        // deploy contract; constructor sets owner and admin to deployer
        c = new C();
        admin = address(this); // the test contract is the deployer
    }

    // fuzz the new owner address; the rule: setOwner called by admin always returns true (in reference)
    function testFuzz_property(address newOwner) public {
        // keep the domain wide; allow any address including zero
        // call setOwner as admin (this contract is admin)
        bool ok;
        try c.setOwner(newOwner) returns (bool ret) {
            // call succeeded; record whether returned value equals true
            ok = ret;
        } catch {
            // if it reverted, mark as false (but in reference it should not revert when called by admin)
            ok = false;
        }

        // The reference implementation always returns true for any newOwner when called by admin.
        // The mutant that returns (_owner == owner) will return false for inputs where newOwner != previous owner,
        // so this assert will pass on reference for all inputs and fail on the mutant for some inputs.
        assertTrue(ok);
    }
}

