pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz the address to be set as owner. The rule: for any fuzzed owner address,
    // calling setOwner as admin completes and returns true in the reference.
    // The mutant may return false for some _owner values (when it compares to previous owner),
    // so this test will fail on the mutant for some fuzzed inputs.
    function testFuzz_property(address newOwner) public {
        // widen domain: allow any address (including zero);
        // ensure the caller is the admin (deployer from setUp). Use vm.prank to call as admin.
        bool ok;
        vm.prank(address(this)); // set msg.sender to this test contract by default (not admin)
        // The contract's admin is the deployer of C which is this test's address (setUp called new C() from this contract),
        // so we must call setOwner as that admin. Use vm.prank(address(this)). However, vm.prank affects the next call only,
        // so we directly make the call under that prank.
        vm.prank(address(this));
        try c.setOwner(newOwner) returns (bool ret) {
            ok = ret;
        } catch {
            // should not revert under reference for any newOwner since onlyAdmin (we call as admin)
            ok = false;
        }

        // The reference implementation always returns true after successful call; assert that return is true.
        // This single assertion is satisfied by the correct contract for all inputs, but the mutant returns false for some inputs.
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public { 
        c = new C();
        // constructor set owner to msg.sender (this test contract), and admin is private set to msg.sender in constructor of C
        // But in the contract C provided, admin is set to payable(msg.sender) at declaration time (msg.sender is this test contract when deployed by Foundry),
        // so this test contract is the admin. We capture address(this) as admin for clarity.
        admin = address(this);
    }

    // Fuzz parameter: the new owner address to set. The fuzzer will search for a value that makes the mutant differ.
    function testFuzz_property(address newOwner) public {
        // admissible domain: newOwner can be any address (including zero). Keep wide, no assumptions.

        // Call setOwner as admin (this contract is admin already), capture whether the call completed and the returned bool.
        bool ok;
        bool ret;
        try c.setOwner(newOwner) returns (bool r) { ok = true; ret = r; } catch { ok = false; ret = false; }

        // General rule: in the reference contract, any successful setOwner call returns true.
        // So for all inputs where the call does not revert (ok == true), the return value must be true.
        // The mutant can produce ok == true but ret == false for some newOwner values.
        assertTrue(!ok || ret);
    }
}

