pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public {
        // deploy C; its constructor sets owner and records admin as msg.sender
        // we deploy from this contract, but want admin to be some fuzzable EOA later
        c = new C();
        // the deploying address is this test contract; record it as admin for clarity
        admin = address(this);
    }

    // fuzzed parameter: any address newOwner; the fuzzer will search for inputs
    function testFuzz_property(address newOwner) public {
        // WIDE admissible domain: ensure newOwner is any address (including zero)
        // We must call setOwner as the admin (this contract). Since setUp deployed c from this contract,
        // msg.sender == admin for the contract's onlyAdmin modifier when called from here.
        // Call setOwner and capture whether it returned true via try/catch and the return value.

        bool ok;
        try c.setOwner(newOwner) returns (bool ret) {
            ok = ret;
        } catch {
            // If it reverts, mark ok = false
            ok = false;
        }

        // The reference implementation guarantees that whenever the call completes (does not revert), it returns true.
        // We therefore assert that ok is true. This is a single assertTrue over an observable (the returned boolean captured).
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public {
        c = new C();
        // deployer of test (this contract) is not the same as C's constructor caller; setUp runs in this contract,
        // but C() was constructed by this test contract, so msg.sender inside C's constructor is this test contract.
        // The C implementation stores owner=msg.sender and admin=msg.sender (private). To call onlyAdmin,
        // we must call setOwner from the same address that deployed C: that's this test contract.
        admin = address(this);
    }

    // fuzz the _owner address — the deciding parameter — wide domain
    function testFuzz_property(address newOwner) public {
        // keep domain wide; disallow zero address? allow zero address too since reference still returns true.
        // No vm.assume to avoid excluding bug-triggering inputs.

        // Call setOwner as admin (this contract). Capture whether call succeeded and what it returned.
        bool ok;
        bool ret;
        // perform low-level call to capture returned boolean without causing test revert on unexpected return
        (ok, ) = address(c).call(abi.encodeWithSelector(C.setOwner.selector, newOwner));

        // If call succeeded, the correct contract always returns true. We therefore assert that whenever the call
        // does not revert, the return value (read via try/catch calling the function directly) is true.
        // Use try/catch to obtain the returned bool value; the try branch will execute only if the external call did not revert.
        try c.setOwner(newOwner) returns (bool r) {
            ret = r;
        } catch {
            // if it reverted, set ret to false (unused) — but we will only assert in the non-revert case
            ret = false;
        }

        // Single assertion: whenever the call completed (ok == true), the returned boolean must be true.
        // The reference implementation always satisfies this; the mutant can complete while returning false for some newOwner.
        assertTrue(!ok || ret);
    }
}
